mapper.select:
SELECT b.ID AS id, b.IDEMPOTENT_KEY AS idempotentKey, b.BIZ_TYPE AS bizType, b.BIZ_ID AS bizId, b.REQUEST_HASH AS requestHash, b.RESULT_REF AS resultRef, b.EXPIRE_AT_MS AS expireAtMs, b.ENV_CODE AS envCode, b.DELETED AS deleted, b.CREATE_USER AS createUser, b.CREATE_TIME AS createTime, b.UPDATE_USER AS updateUser, b.UPDATE_TIME AS updateTime FROM AST_FLOW_BIZ_IDEMPOTENT b WHERE (b.DELETED = 0 OR b.DELETED IS NULL)
AND b.IDEMPOTENT_KEY = #{req.idempotentKey}
AND b.BIZ_TYPE = #{req.bizType}
AND b.BIZ_ID = #{req.bizId}
AND b.ENV_CODE = #{req.envCode}
ORDER BY b.UPDATE_TIME DESC, b.ID DESC
